export function getSubtypeContent(category, subtype) {
  return subtypeContent[category]?.[subtype] ?? null;
}

export function getAllSubtypes() {
  const all = [];
  for (const category of Object.keys(subtypeContent)) {
    for (const subtype of Object.keys(subtypeContent[category])) {
      all.push({ category, subtype });
    }
  }
  return all;
}

